class TestKeyLifecycle:
    """INV-001: Creation, rotation, and expiration of quantum keys."""

    def test_key_creation_returns_valid_entry(self, key_manager):
        """Keys must be created with unique IDs and correct metadata."""
        key_id, entry = key_manager.create_key()
        assert key_id is not None
        assert isinstance(entry, KeyEntry)
        assert len(entry.key_material) == TEST_KEY_SIZE
        assert entry.created_at > 0
        assert entry.expires_at == entry.created_at + TEST_TTL
        assert entry.status == 'active'

    def test_key_rotation_generates_new_material(self, key_manager):
        """Rotation must invalidate old key and produce fresh material."""
        old_id, old_entry = key_manager.create_key()
        new_id, new_entry = key_manager.rotate_key(old_id)
        assert new_id != old_id
        assert new_entry.key_material != old_entry.key_material
        assert old_entry.status == 'rotated'
        assert new_entry.status == 'active'

    @freeze_time("2026-01-01 00:00:00")
    def test_key_expiration_after_ttl(self, key_manager):
        """Keys must expire exactly after TTL seconds."""
        key_id, entry = key_manager.create_key()
        assert key_manager.is_valid(key_id) is True
        # Advance time beyond TTL
        with freeze_time("2026-01-01 00:01:01"):
            assert key_manager.is_valid(key_id) is False
            with pytest.raises(KeyExpiredError):
                key_manager.get_key(key_id)

    @given(st.integers(min_value=1, max_value=100))
    @settings(max_examples=50, suppress_health_check=[HealthCheck.too_slow])
    def test_key_id_uniqueness_property(self, key_manager, count):
        """Property: All generated key IDs must be unique."""
        ids = set()
        for _ in range(count):
            key_id, _ = key_manager.create_key()
            ids.add(key_id)
        assert len(ids) == count

    def test_key_cleanup_removes_expired(self, key_manager):
        """Cleanup must purge expired keys and free capacity."""
        for _ in range(TEST_MAX_KEYS):
            key_manager.create_key()
        assert key_manager.active_count() == TEST_MAX_KEYS
        with freeze_time("2026-01-01 00:02:00"):
            key_manager.cleanup_expired()
        assert key_manager.active_count() == 0


