class TestCryptoPrimitives:
    """INV-002: Kyber KEM operations must be correct and deterministic."""

    def test_keypair_generation(self, crypto_engine):
        """Keypair must produce public and secret keys of correct size."""
        pub, sec = crypto_engine.generate_keypair()
        assert len(pub) == 32
        assert len(sec) == 32
        assert pub != sec

    def test_encapsulation_roundtrip(self, crypto_engine):
        """Encapsulation must produce ciphertext and shared secret."""
        pub, sec = crypto_engine.generate_keypair()
        ciphertext, shared_secret = crypto_engine.encapsulate(pub)
        assert len(ciphertext) == 32
        assert len(shared_secret) == 32

    def test_decapsulation_matches(self, crypto_engine):
        """Decapsulation must recover the same shared secret."""
        pub, sec = crypto_engine.generate_keypair()
        ciphertext, shared_secret = crypto_engine.encapsulate(pub)
        recovered = crypto_engine.decapsulate(ciphertext, sec)
        assert recovered == shared_secret

    def test_wrong_secret_key_fails(self, crypto_engine):
        """Decapsulation with wrong secret key must raise error."""
        pub1, sec1 = crypto_engine.generate_keypair()
        pub2, sec2 = crypto_engine.generate_keypair()
        ciphertext, _ = crypto_engine.encapsulate(pub1)
        with pytest.raises(GatewayError):
            crypto_engine.decapsulate(ciphertext, sec2)

    @given(st.binary(min_size=16, max_size=64))
    @settings(max_examples=20)
    def test_encapsulation_deterministic(self, crypto_engine, public_key):
        """Property: Same public key yields different ciphertexts (fresh randomness)."""
        c1, _ = crypto_engine.encapsulate(public_key)
        c2, _ = crypto_engine.encapsulate(public_key)
        assert c1 != c2  # Non-deterministic encapsulation (IND-CCA2)


