class TestConcurrency:
    """INV-003: System must handle concurrent operations without corruption."""

    def test_concurrent_key_creation(self, key_manager):
        """Multiple threads creating keys must not collide."""
        results = []
        errors = []
        lock = threading.Lock()

        def worker():
            try:
                key_id, entry = key_manager.create_key()
                with lock:
                    results.append((key_id, entry))
            except Exception as e:
                with lock:
                    errors.append(e)

        threads = [threading.Thread(target=worker) for _ in range(20)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        assert len(errors) == 0
        assert len(results) == 20
        # All IDs unique
        ids = [r[0] for r in results]
        assert len(set(ids)) == 20

    def test_concurrent_rotation_same_key(self, key_manager):
        """Concurrent rotation of same key must yield single winner."""
        key_id, _ = key_manager.create_key()
        results = []
        lock = threading.Lock()

        def worker():
            try:
                new_id, entry = key_manager.rotate_key(key_id)
                with lock:
                    results.append((new_id, entry))
            except Exception as e:
                with lock:
                    results.append(('error', e))

        threads = [threading.Thread(target=worker) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        # Only one successful rotation, rest should fail gracefully
        successes = [r for r in results if r[0] != 'error']
        assert len(successes) == 1

    def test_async_concurrent_operations(self, gateway, event_loop_policy):
        """Async operations must not deadlock or corrupt state."""
        async def run_operations():
            tasks = []
            for _ in range(10):
                tasks.append(gateway.request_key_async())
            return await asyncio.gather(*tasks, return_exceptions=True)

        results = event_loop_policy.run_until_complete(run_operations())
        successful = [r for r in results if not isinstance(r, Exception)]
        assert len(successful) == 10

    def test_concurrency_limit_enforced(self, gateway):
        """System must reject operations beyond MAX_CONCURRENT_OPERATIONS."""
        # Simulate max concurrency
        for _ in range(TEST_MAX_CONCURRENCY):
            gateway._acquire_slot()
        with pytest.raises(ConcurrencyLimitError):
            gateway._acquire_slot()
        # Release and retry
        gateway._release_slot()
        gateway._acquire_slot()  # Should succeed now


