class TestResourceLimits:
    """INV-004: System must enforce limits and clean up resources properly."""

    def test_max_active_keys_enforced(self, key_manager):
        """Creating beyond MAX_ACTIVE_KEYS must raise ResourceLimitError."""
        for _ in range(TEST_MAX_KEYS):
            key_manager.create_key()
        with pytest.raises(ResourceLimitError):
            key_manager.create_key()

    def test_key_deletion_frees_capacity(self, key_manager):
        """Deleting keys must free capacity for new keys."""
        keys = [key_manager.create_key()[0] for _ in range(TEST_MAX_KEYS)]
        with pytest.raises(ResourceLimitError):
            key_manager.create_key()
        key_manager.delete_key(keys[0])
        key_manager.create_key()  # Should succeed now

    def test_shutdown_cleans_all_resources(self, key_manager):
        """Shutdown must release all locks and clear state."""
        for _ in range(TEST_MAX_KEYS):
            key_manager.create_key()
        key_manager.shutdown()
        assert key_manager.active_count() == 0
        assert key_manager._lock is None  # Lock released

    def test_gateway_shutdown_cleanup(self, gateway):
        """Gateway shutdown must propagate to all components."""
        gateway.request_key()
        gateway.shutdown()
        assert gateway._is_shutdown is True
        with pytest.raises(GatewayError):
            gateway.request_key()

    @given(st.integers(min_value=1, max_value=50))
    @settings(max_examples=20)
    def test_resource_usage_never_exceeds_limit(self, key_manager, num_ops):
        """Property: Active keys never exceed MAX_ACTIVE_KEYS."""
        for i in range(num_ops):
            try:
                key_manager.create_key()
            except ResourceLimitError:
                break
        assert key_manager.active_count() <= TEST_MAX_KEYS


