    def test_memory_pressure_handling(self, key_manager):
        """System must survive simulated memory exhaustion."""
        with patch.object(key_manager, '_store_key', side_effect=MemoryError):
            with pytest.raises(ResourceLimitError):
                key_manager.create_key()
        # Recovery
