class TestPerformance:
    """Performance benchmarks with strict thresholds."""

    def test_key_creation_latency(self, key_manager):
        """Key creation must complete under 10ms."""
        start = time.perf_counter()
        for _ in range(100):
            key_manager.create_key()
        elapsed = (time.perf_counter() - start) / 100
        assert elapsed < 0.01  # 10ms threshold

    def test_concurrent_throughput(self, key_manager):
        """System must handle 1000 ops/sec under concurrency."""
        start = time.perf_counter()
        threads = []
        results = Counter()

        def worker():
            for _ in range(50):
                try:
                    key_manager.create_key()
                    results['success'] += 1
                except ResourceLimitError:
                    results['limit'] += 1

        for _ in range(20):
            t = threading.Thread(target=worker)
            threads.append(t)
            t.start()
        for t in threads:
            t.join()
        elapsed = time.perf_counter() - start
        total_ops = results['success'] + results['limit']
        assert total_ops / elapsed > 1000  # 1000 ops/sec

    def test_memory_footprint(self, key_manager):
        """Memory usage must stay bounded."""
        import tracemalloc
        tracemalloc.start()
        for _ in range(100):
            key_manager.create_key()
        current, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()
        assert peak < 10 * 1024 * 1024  # 10MB peak


